const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza minimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

const resultados = $input.all().map((item, i) => {
  // o webhook entrega os dados dentro de "body"
  const dados = item.json.body ?? item.json;
  const cliente = dados.cliente ?? "Cliente";
  const assunto = dados.assunto ?? "";
  const prioridade = dados.prioridade ?? "normal";

  const protocolo = "CH-" + String(Date.now()).slice(-6) + i;

  // regra simples: setor conforme palavras do assunto
  const texto = assunto.toLowerCase();
  let setor = "Suporte geral";
  let motivo = "assunto_geral";
  if (texto.includes("liga") || texto.includes("tela") || texto.includes("hardware")) {
    setor = "Suporte de hardware";
    motivo = "palavra_hardware";
  } else if (texto.includes("internet") || texto.includes("rede") || texto.includes("wifi")) {
    setor = "Suporte de redes";
    motivo = "palavra_rede";
  }

  const mensagens = [
    `Olá ${cliente}! Recebemos seu chamado (${protocolo}) sobre "${assunto}". Ele foi encaminhado para ${setor} com prioridade ${prioridade}.`,
    `Oi ${cliente}! Seu chamado ${protocolo} está registrado: "${assunto}". Setor responsável: ${setor}. Prioridade: ${prioridade}.`,
    `${cliente}, chamado ${protocolo} aberto. Assunto: "${assunto}". Vamos tratar com ${setor} (prioridade ${prioridade}).`
  ];

  return {
    protocolo,
    cliente,
    assunto,
    prioridade,
    setor,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

return [{
  json: {
    ok: true,
    total_chamados: resultados.length,
    resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

const originais = $("Code in JavaScript2").all().map(i => i.json);


const respostasIA = $input.all();


function pegarTexto(item) {
  const d = item.json;
  return (
    d.output ??
    d.text ??
    d.content?.parts?.[0]?.text ??
    d.candidates?.[0]?.content?.parts?.[0]?.text ??
    d.message?.content ??
    ""
  );
}


function lerJSON(texto) {
  try {
    const limpo = String(texto).replace(/```json|```/g, "").trim();
    return JSON.parse(limpo);
  } catch (e) {
    return null;
  }
}

const out = respostasIA.map((item, i) => {
  const j = originais[i] ?? {};
  const ia = lerJSON(pegarTexto(item));

  const to = j.email_to ?? j.email ?? "";
  const subject = ia?.subject ?? `Uma recomendação para você, ${j.nome ?? ""}`;
  const text_body = ia?.text_body ?? j.mensagem_base ?? "";
  const html_body = ia?.html_body ?? `<p>${text_body}</p>`;

  return {
    json: {
      ok: true,
      to,
      subject,
      text_body,
      html_body,


      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});

return out;
